-- Migration 048: pictures (public/lec/gd-*.svg) on the Графикалық дизайн slides of 047. Idempotent: sets slide.img/alt by lesson number and slide title.
-- GENERATED by scripts/gen-gd.mjs. A fresh database does not need it: 047 is generated with the pictures already in.

do $gdimg$
declare r record; n int := 0;
begin
  for r in select * from (values
    ($sl$7.1$sl$, $sl$Figma қалай құрылған$sl$, $sl$lec/gd-figma-layout.svg$sl$, $sl$Figma терезесі: сол жақта Layers, ортада Frame, оң жақта Design панелі$sl$, true),
    ($sl$7.2$sl$, $sl$Негізгі құралдар$sl$, $sl$lec/gd-tools-robot.svg$sl$, $sl$Rectangle, Ellipse және Text құралдарынан жиналған робот$sl$, false),
    ($sl$7.3$sl$, $sl$Вектор (vector)$sl$, $sl$lec/gd-raster-vector.svg$sl$, $sl$Растр дөңгелегінің шеті сатылы, вектор дөңгелегінің шеті тегіс$sl$, false),
    ($sl$7.4$sl$, $sl$Pen tool (P)$sl$, $sl$lec/gd-pen.svg$sl$, $sl$Pen tool: түзу және қисық нүктелер, тұтқалар$sl$, false),
    ($sl$7.4$sl$, $sl$Boolean амалдары$sl$, $sl$lec/gd-boolean.svg$sl$, $sl$Union, Subtract, Intersect, Exclude нәтижелері$sl$, false),
    ($sl$7.5$sl$, $sl$Жақсы prompt$sl$, $sl$lec/gd-prompt.svg$sl$, $sl$Prompt-тың бес бөлігі: кім, не істейді, стиль, түс, фон$sl$, false),
    ($sl$7.6$sl$, $sl$Калька әдісі$sl$, $sl$lec/gd-trace.svg$sl$, $sl$Растр 50% мөлдір, үстінен контур, соңында вектор$sl$, false),
    ($sl$7.7$sl$, $sl$Жинау және Export$sl$, $sl$lec/gd-sticker-grid.svg$sl$, $sl$Төрт стикер 2 по 2 торда, ақ шетімен$sl$, false),
    ($sl$9.1$sl$, $sl$UX және UI$sl$, $sl$lec/gd-ux-ui.svg$sl$, $sl$UI экранның көрінісі, UX мақсатқа аз қадаммен жету$sl$, false),
    ($sl$9.2$sl$, $sl$Тапсырма шарты$sl$, $sl$lec/gd-card-anatomy.svg$sl$, $sl$Карточка құрылымы: сурет, тақырып, мәтін, батырма$sl$, true),
    ($sl$9.3$sl$, $sl$Auto layout параметрлері$sl$, $sl$lec/gd-autolayout.svg$sl$, $sl$Auto layout: padding, gap, direction$sl$, false),
    ($sl$9.3$sl$, $sl$Resizing: Hug, Fill, Fixed$sl$, $sl$lec/gd-resizing.svg$sl$, $sl$Мәтін ұзарғанда Hug, Fill және Fixed қалай өзгереді$sl$, false),
    ($sl$9.4$sl$, $sl$Екі өлшем$sl$, $sl$lec/gd-responsive.svg$sl$, $sl$Телефон 390 px бір баған, компьютер 1440 px үш баған$sl$, true),
    ($sl$9.5$sl$, $sl$Variants$sl$, $sl$lec/gd-variants.svg$sl$, $sl$Component set: Default, Hover, Disabled және instance-тар$sl$, false),
    ($sl$9.6$sl$, $sl$Мәселе карточкасы$sl$, $sl$lec/gd-ux-card.svg$sl$, $sl$Мәселе карточкасының алты бөлігі$sl$, false),
    ($sl$9.7$sl$, $sl$Қайта дизайндау жолы$sl$, $sl$lec/gd-before-after.svg$sl$, $sl$Шатасқан экран мен таза экранды салыстыру$sl$, false)
  ) as t(pref, stitle, img, alt, dropcode)
  loop
    update public.cf_lessons l set updated_at = now(), slides = (
      select jsonb_agg(case when s->>'title' = r.stitle then (case when r.dropcode then s - 'code' - 'lang' else s end) || jsonb_build_object('img', r.img, 'alt', r.alt) else s end order by o)
      from jsonb_array_elements(l.slides) with ordinality a(s, o))
    where l.subject = 'Графикалық дизайн' and l.title like r.pref || ' %';
    get diagnostics n = row_count;
    if n <> 1 then raise exception 'lesson % updated % rows', r.pref, n; end if;
  end loop;
